{"cards": [{"node_code": "N_841ca33e5769ab32", "definition": "研究甲型（HAV）与戊型（HEV）肝炎病毒的生物学特性、传播途径、致病机制及预防策略，重点涵盖其急性感染特征、粪-口传播规律及疫苗研发进展。", "boundary": "本节点专指HAV与HEV。两者均为RNA病毒，主要经粪-口途径传播，通常引起急性肝炎，极少慢性化。与乙、丙、丁型肝炎病毒的区别在于传播途径（非血液/性接触为主）及病程（急性为主）。涵盖病毒结构、流行病学特征、诊断方法及预防接种。", "includes": ["甲型与戊型肝炎病毒的基因组结构、复制周期及致病机制", "粪-口传播途径的流行病学特征与急性感染临床表现", "甲肝疫苗及戊肝疫苗的研发原理、应用及预防策略"], "excludes": ["乙型、丙型或丁型肝炎病毒的研究（归入乙型、丙型与丁型肝炎病毒节点）", "非病毒性因素引起的急性肝损伤（如药物性、酒精性肝炎）"], "sibling_distinctions": [{"other_code": "N_38e7e531526447c0", "rule": "甲型与戊型肝炎病毒主要经粪-口途径传播，病程多为急性，极少慢性化；乙型、丙型与丁型肝炎病毒主要经血液、体液传播，易导致慢性感染、肝硬化及肝癌。"}], "cross_boundary_rule": ""}, {"node_code": "N_38e7e531526447c0", "definition": "研究乙型（HBV）、丙型（HCV）及丁型（HDV）肝炎病毒的生物学特性、慢性感染机制、免疫逃逸及抗病毒治疗策略，重点涵盖其血液传播特征及肝纤维化进程。", "boundary": "本节点专指HBV、HCV与HDV。三者主要经血液、性接触及母婴途径传播，易导致慢性肝炎、肝硬化及肝细胞癌。与甲、戊型肝炎病毒的区别在于传播途径（非粪-口为主）及病程（慢性化风险高）。涵盖病毒基因分型、耐药机制、特异性诊断标志物及靶向治疗。", "includes": ["乙型、丙型与丁型肝炎病毒的基因组结构、复制周期及慢性化机制", "血液、性接触及母婴传播途径的流行病学特征与免疫病理过程", "HBV/HCV/HDV的基因分型、耐药监测及特异性抗病毒药物作用机制"], "excludes": ["甲型或戊型肝炎病毒的研究（归入甲型与戊型肝炎病毒节点）", "非病毒性因素引起的慢性肝病（如非酒精性脂肪性肝病）"], "sibling_distinctions": [{"other_code": "N_841ca33e5769ab32", "rule": "乙型、丙型与丁型肝炎病毒主要经血液、体液传播，易慢性化并进展为肝硬化或肝癌；甲型与戊型肝炎病毒主要经粪-口途径传播，病程多为急性，极少慢性化。"}], "cross_boundary_rule": ""}]}
